  '[{"id":"8b378605-c09a-5d14-8ec5-a372682ec95d","question":"Is Alexandria worth a day trip from Cairo?","answer":"Yes, if you leave by 7am. The drive is 2.5 to 3 hours each way, so an early start leaves 6 to 7 hours on the ground, which covers 4 sites and lunch. Leaving at 9 gives you 4 rushed hours and most of them in traffic between stops. With any flexibility, 1 overnight is much better value."},{"id":"e84ad09a-c7de-522d-a8ac-552bde93e599","question":"Is it better to take the train or drive to Alexandria?","answer":"The train is better for solo travellers and couples: about 2.5 hours from Ramses station, comfortable, cheap, and it bypasses the Desert Road. A car and driver costs more but removes the 4 or 5 taxi negotiations you will otherwise need, because Alexandria''s sites are spread along roughly 15 km of coast."},{"id":"32d64636-23f4-58d9-a9f0-444b17f11bbd","question":"How many sites can you see in one day in Alexandria?","answer":"4, plus lunch. The catacombs of Kom el Shoqafa, the Roman theatre at Kom el Dikka, the Bibliotheca Alexandrina and Qaitbay Citadel make a coherent line along the coast. Any itinerary promising 6 or 7 stops is counting photo pauses, so ask how many hours are on the ground before asking what is included."},{"id":"099cfdd5-952a-51d5-a7e7-36ce3f605692","question":"What is the best thing to see in Alexandria?","answer":"The Catacombs of Kom el Shoqafa. A Roman tomb complex cut 3 levels into the rock, found in 1900 when a donkey fell into it, decorated with Egyptian gods in Roman dress and a Medusa over a doorway. That fusion of styles exists nowhere else. The lowest of the 3 levels is usually flooded and closed."},{"id":"96908e91-bdb1-535c-b050-94cf674cdd6b","question":"How long does it take to get from Cairo to Alexandria?","answer":"2.5 to 3 hours by car on the Desert Road, and about 2.5 hours by express train between Ramses and Misr stations. Traffic leaving Cairo is the variable: a 6:30 departure and a 9am departure can differ by 90 minutes on the same road, which is why the start time decides the whole day."},{"id":"fd392203-dab6-5298-b381-6cc4c5fb6b62","question":"Can you see ancient Alexandria?","answer":"Very little of it. The Ptolemaic city lies under the modern one, the Pharos lighthouse collapsed in earthquakes between the 10th and 14th centuries, and the ancient library is a story rather than a site. What survives above ground is mostly Roman: the catacombs, the theatre at Kom el Dikka and Pompey''s Pillar."},{"id":"5548d06c-85b4-5d14-9342-0272efd643d1","question":"Is Alexandria better as a day trip or an overnight stay?","answer":"Overnight, if your schedule allows it. The same 5 to 6 hours of driving then serves 2 relaxed half days instead of 1 compressed one, and you get the corniche in the evening, which is when the city is at its best. A hotel night usually costs less than a second day of car hire later in a trip."},{"id":"7909f072-1e47-58fc-9087-a4212e1e34a8","question":"What should you eat in Alexandria?","answer":"Seafood, at one of the fish restaurants around the Eastern Harbour. You choose from ice at the front, it is weighed, and it comes grilled with salads and bread. Ask the price per kilo before you point, because that is where confusion arises. Budget 1 hour and eat around 1pm, between 2 sites."}]'::jsonb,
  -- The other SEO overrides stay NULL on purpose: canonical_url falls back to
  -- the page's own URL, robots to "index, follow", og_image to the hero. An
  -- empty string in any of them would defeat that fallback.
  'BlogPosting'
)
ON CONFLICT (slug) DO UPDATE SET
  title_en = EXCLUDED.title_en,
  -- The body is NOT overwritten once images are in it.
  --
  -- This file used to assign EXCLUDED.body_en unconditionally, and re-running
  -- it after scripts/fill-post-images.ts deleted every <figure> that script had
  -- inserted. Silently, with the file reporting success. The CASE makes a
  -- re-run safe: a row that has already been illustrated keeps its body, and
  -- the verification below says which rows were kept so it is never a surprise.
  --
  -- To change the prose of a row that has figures, patch it surgically instead.
  -- See content-updates/blog-generator/README.md.
  body_en = CASE
    WHEN posts.body_en LIKE '%<figure%' THEN posts.body_en
    ELSE EXCLUDED.body_en
  END,
  excerpt = EXCLUDED.excerpt,
  category = EXCLUDED.category,
  tags = EXCLUDED.tags,
  focus_keyword = EXCLUDED.focus_keyword,
  meta_title = EXCLUDED.meta_title,
  meta_description = EXCLUDED.meta_description,
  status = EXCLUDED.status,
  scheduled_at = EXCLUDED.scheduled_at,
  faqs = EXCLUDED.faqs,
  schema_type = EXCLUDED.schema_type,
  updated_at = now();

COMMIT;

-- ---------------------------------------------------------------------------
-- Verification. Every "bad" column below must read 0.
-- ---------------------------------------------------------------------------

-- Not a failure. On a first run this reads "body written". On a re-run against
-- a row that already has images it reads "body kept, it has figures in it",
-- which is the guard above doing its job rather than something going wrong.
SELECT CASE
         WHEN body_en LIKE '%<figure%' THEN 'body kept, it has figures in it'
         ELSE 'body written from this file'
       END AS body_en_outcome,
       (length(body_en) - length(replace(body_en, '<figure', ''))) / 7 AS figures
FROM posts WHERE slug = 'alexandria-day-trip-from-cairo';
SELECT slug,
       length(meta_title) AS title_len,
       length(meta_description) AS meta_len,
       jsonb_array_length(faqs) AS faq_count,
       array_length(regexp_split_to_array(regexp_replace(body_en, '<[^>]+>', ' ', 'g'), '\s+'), 1) AS body_words,
       scheduled_at,
       schema_type,
       (SELECT count(*) FROM regexp_matches(body_en, 'alexandria day trip from cairo', 'gi')) AS primary_hits
FROM posts WHERE slug = 'alexandria-day-trip-from-cairo';

SELECT 'seo lengths out of range' AS check, count(*) AS bad FROM posts
WHERE slug = 'alexandria-day-trip-from-cairo' AND (length(meta_title) > 60 OR length(meta_description) NOT BETWEEN 150 AND 160);

SELECT 'faq count out of range' AS check, count(*) AS bad FROM posts
WHERE slug = 'alexandria-day-trip-from-cairo' AND jsonb_array_length(faqs) NOT BETWEEN 7 AND 8;

-- Answers are written to be quoted on their own by an AI answer engine, which
-- means 40 to 80 words each. Outside that they are either empty or too long.
SELECT 'faq answers outside 40-80 words' AS check, count(*) AS bad
FROM posts p, jsonb_array_elements(p.faqs) f
WHERE p.slug = 'alexandria-day-trip-from-cairo'
  AND array_length(regexp_split_to_array(trim(f->>'answer'), '\s+'), 1) NOT BETWEEN 40 AND 80;

-- The SEO overrides must be NULL, not empty strings, or the fallbacks break.
SELECT 'seo overrides stored as empty strings' AS check, count(*) AS bad FROM posts
WHERE slug = 'alexandria-day-trip-from-cairo'
  AND (canonical_url = '' OR robots = '' OR og_image = '' OR schema_type = '' OR featured_image_alt = '');

SELECT 'faq entries missing id, question or answer' AS check, count(*) AS bad
FROM posts p, jsonb_array_elements(p.faqs) f
WHERE p.slug = 'alexandria-day-trip-from-cairo'
  AND (coalesce(f->>'id','') = '' OR coalesce(f->>'question','') = '' OR coalesce(f->>'answer','') = '');

SELECT 'em or en dash present' AS check, count(*) AS bad FROM posts
WHERE slug = 'alexandria-day-trip-from-cairo'
  AND (body_en ~ '[\u2013\u2014]' OR meta_title ~ '[\u2013\u2014]' OR meta_description ~ '[\u2013\u2014]' OR title_en ~ '[\u2013\u2014]');

-- Tour links must sit at the site root. Anything under the category path 404s.
SELECT 'tour links under /luxury-egypt-tour-packages/' AS check, count(*) AS bad FROM posts
WHERE slug = 'alexandria-day-trip-from-cairo' AND body_en ~ 'href="/luxury-egypt-tour-packages/[^"]';

SELECT 'root-relative internal links' AS check,
       (SELECT count(*) FROM regexp_matches(body_en, 'href="/[^"]+"', 'g')) AS good,
       (SELECT count(*) FROM regexp_matches(body_en, 'href="(?!/)[^"]+"', 'g')) AS bad
FROM posts WHERE slug = 'alexandria-day-trip-from-cairo';

SELECT 'unfilled placeholders' AS check,
       (SELECT count(*) FROM regexp_matches(body_en, 'data-placeholder=', 'g'))
     + (SELECT count(*) FROM regexp_matches(body_en, '\{\{[A-Z_]+\}\}', 'g')) AS remaining
FROM posts WHERE slug = 'alexandria-day-trip-from-cairo';

SELECT 'other language columns left empty' AS check, count(*) AS bad FROM posts
WHERE slug = 'alexandria-day-trip-from-cairo'
  AND (title_es IS NOT NULL OR title_fr IS NOT NULL OR title_jp IS NOT NULL
       OR body_es IS NOT NULL OR body_fr IS NOT NULL OR body_jp IS NOT NULL);
